local function selectSky(key,label,b,apply)
 state.serial=state.serial+1
 local ticket=state.serial
 status.Text='Loading '..label..'...'
 apply.Text='LOADING'
 local loadStarted=os.clock()
 task.spawn(function()
  local ok,a,err
  if string.sub(key,1,8)=='V9EXTRA_' then
   ok,a,err=pcall(function()
    local engine=env.TORNHUB_V9_SKY_ENGINE
    if not engine or type(engine.Apply)~='function' then
     local source=game:HttpGet('https://raw.githubusercontent.com/lyn4x-js/New-/main/TORNHUB_V9_SKY_ENGINE.lua')
     local fn,compileErr=loadstring(source)
     if not fn then error(compileErr or 'V9 sky engine compile failed') end
     engine=fn()
    end
    local success,message=engine.Apply(label)
    if not success then error(message or 'V9 sky failed') end
    return true
   end)
  else
   ok,a,err=pcall(assetsFor,key)
  end
  local remaining=1-(os.clock()-loadStarted)
  if remaining>0 then task.wait(remaining) end
  if state.closed or ticket~=state.serial then return end
  if not ok or not a then
   status.Text='Error: '..tostring(ok and err or a)
   apply.Text='RETRY'
   warn('[tornhub] '..status.Text)
   return
  end
  if activeButton and activeButton~=b then
   activeButton.BackgroundColor3=surface
   local old=activeButton:FindFirstChild('Apply')
   if old then old.Text='APPLY';old.BackgroundColor3=Color3.fromRGB(27,28,34);old.TextColor3=white end
  end
  state.active=key
  if string.sub(key,1,8)~="V9EXTRA_" then putSky(key) end
  activeButton=b
  b.BackgroundColor3=Color3.fromRGB(47,32,22)
  apply.Text='ACTIVE';apply.BackgroundColor3=orange;apply.TextColor3=Color3.fromRGB(12,12,15)
  status.Text='Active: '..label
  task.delay(1,function() if not state.closed and state.active==key and string.sub(key,1,8)~="V9EXTRA_" then putSky(key) end end)
 end)
end
