local tornJsonState={connections={},saved={}}
local function tornApplyJsonPack(name)
 local rules=TORN_JSON_TEXTURES[name]
 if not rules then error('Unknown JSON pack: '..tostring(name)) end
 if type(writefile)~='function' or type(getcustomasset)~='function' then error('Delta requires writefile + getcustomasset') end
 for _,c in ipairs(tornJsonState.connections) do pcall(function()c:Disconnect()end) end
 tornJsonState.connections={}
 for inst,props in pairs(tornJsonState.saved) do
  if inst.Parent then for prop,old in pairs(props) do pcall(function()inst[prop]=old end) end end
 end
 tornJsonState.saved={}
 local replacements={}
 for i,rule in ipairs(rules) do
  local bytes=game:HttpGet(rule.url)
  if type(bytes)~='string' or #bytes<64 then error('Download failed: '..name..' asset '..i) end
  local ext=rule.url:match('%.([%a%d]+)%??[^/]*$') or 'png'
  local path='TORNHUB_JSON_'..name:gsub('[^%w]','_')..'_'..i..'.'..ext
  writefile(path,bytes)
  local asset=getcustomasset(path)
  for _,id in ipairs(rule.ids) do replacements[id]=asset end
 end
 local properties={Decal={'Texture'},Texture={'Texture'},MeshPart={'TextureID'},SpecialMesh={'TextureId'},SurfaceAppearance={'ColorMap'},Sound={'SoundId'},ImageLabel={'Image'},ImageButton={'Image'}}
 local function applyOne(inst)
  local props=properties[inst.ClassName]
  if not props then return end
  for _,prop in ipairs(props) do
   local ok,old=pcall(function()return inst[prop]end)
   if ok and type(old)=='string' then
    for id,asset in pairs(replacements) do
     if old:find(id,1,true) then
      tornJsonState.saved[inst]=tornJsonState.saved[inst] or {}
      if tornJsonState.saved[inst][prop]==nil then tornJsonState.saved[inst][prop]=old end
      pcall(function()inst[prop]=asset end)
      break
     end
    end
   end
  end
 end
 for _,inst in ipairs(game:GetDescendants()) do applyOne(inst) end
 table.insert(tornJsonState.connections,game.DescendantAdded:Connect(applyOne))
 return true
end
