    else
     local code=game:HttpGet(pack[3])
     local chunk,compileErr=loadstring(code)
     if not chunk then error(compileErr or 'Unable to compile script') end
     chunk()
    end
   end)
   local remaining=1-(os.clock()-loadStarted)
   if remaining>0 then task.wait(remaining) end
   textureBusy=false
   if state.closed then return end
   if not ok then
    status.Text='Pack error: '..tostring(err):sub(1,75)
    apply.Text='RETRY'
    warn('[tornhub textures] '..tostring(err))
    return
   end
   if activeTexture and activeTexture~=apply then
    activeTexture.Text='APPLY';activeTexture.BackgroundColor3=Color3.fromRGB(27,28,34);activeTexture.TextColor3=white
   end
   activeTexture=apply
   apply.Text='RAN';apply.BackgroundColor3=orange;apply.TextColor3=Color3.fromRGB(12,12,15)
   status.Text='Launched '..pack[1]..' (script manages its own effects)'
  end)
 end)
 textureButtons[#textureButtons+1]={row=row,name=pack[1]..' '..pack[2]}
end
local infoPanel=round(make('Frame',panel,{BackgroundColor3=Color3.fromRGB(13,14,19),BorderSizePixel=0,Size=UDim2.new(1,-20,1,-20),Position=UDim2.fromOffset(10,10),Visible=false,ZIndex=13}),8)
local infoTitle=text(infoPanel,'',17,15,325,30,21,white,true);infoTitle.ZIndex=14
local infoText=text(infoPanel,'',17,56,335,230,14,soft,false);infoText.ZIndex=14;infoText.TextWrapped=true;infoText.TextYAlignment=Enum.TextYAlignment.Top
local function filter()
 local q=search.Text:lower()
 local target=section=='Skies' and skyButtons or textureButtons
 for _,v in ipairs(target) do v.row.Visible=(q=='' or v.name:lower():find(q,1,true)~=nil) end
end
search:GetPropertyChangedSignal('Text'):Connect(filter)
-- V8: prominent navigation on the right, for mobile users who missed the sidebar.
local function quickTab(label,y,index)
 local b=round(make('TextButton',frame,{Name='Quick'..label,Text=label,Font=Enum.Font.GothamBold,TextSize=17,TextColor3=white,BackgroundColor3=Color3.fromRGB(37,28,24),BorderSizePixel=0,Position=UDim2.fromOffset(574,y),Size=UDim2.fromOffset(242,54),ZIndex=16}),9)
 make('UIStroke',b,{Color=orange,Thickness=1})
 b.Activated:Connect(function()
  local target=sections[index]
  if target then section=target.name; infoPanel.Visible=false; list.Visible=index==1; textureList.Visible=index==2; search.Visible=true; search.Text=''; search.PlaceholderText=index==1 and 'Search skies...' or 'Search textures...'; status.Text=index==1 and 'Choose a sky' or 'Choose a texture pack'; for j,t in ipairs(sections) do t.button.BackgroundTransparency=j==index and .08 or 1 end; filter() end
 end)
 return b
end
quickTab('☁  SKIES',252,1)
quickTab('◉  TEXTURES',318,2)

for i,v in ipairs(sections) do
 v.button.Activated:Connect(function()
  section=v.name
  for j,s in ipairs(sections) do
   s.button.BackgroundTransparency=j==i and .08 or 1
   s.button.BackgroundColor3=Color3.fromRGB(65,38,19)
  end
  infoPanel.Visible=i>2
  list.Visible=i==1
  textureList.Visible=i==2
  search.Visible=i<=2
  if i<=2 then
   search.Text=''
   search.PlaceholderText=i==1 and '⌕   Search skies...' or '⌕   Search textures...'
   status.Text=i==1 and 'Choose a sky' or 'Choose a texture pack'
   filter()
  elseif i==3 then infoTitle.Text='Settings';infoText.Text='Use + and − in the top-right to resize tornhub. Drag the header to move it. Close with × and reopen with the floating button.'
  elseif i==4 then infoTitle.Text='Credits';infoText.Text='tornhub V8 DELTA • skies and textures\nSky and texture packs belong to their respective creators.'
  elseif i==5 then infoTitle.Text='Info';infoText.Text='32 sky presets and 15 external texture scripts. Texture packs launch their original Lua scripts and may also modify sky or sounds. Only run scripts you trust. Preview thumbnails are placeholders until images are supplied.' end
 end)
end
local reopen=round(make('TextButton',gui,{Name='OpenTornHub',Size=UDim2.fromOffset(74,74),Position=UDim2.new(1,-92,.4,0),BackgroundColor3=Color3.fromRGB(12,13,17),Text='tornhub\nV8',TextColor3=orange,Font=Enum.Font.GothamBold,TextSize=14,Visible=false,Active=true,Draggable=false}),37)
make('UIStroke',reopen,{Color=orange,Thickness=2})
local childConn=Lighting.ChildAdded:Connect(function(obj)
 if state.closed or state.applying or not state.active or not obj:IsA('Sky') or obj.Name=='TornHubSky_'..state.active then return end
 task.delay(.2,function()if not state.closed and not state.applying and state.active then putSky(state.active) end end)
end)
function state.Close()
 if state.closed then return end
 state.closed=true;state.serial=state.serial+1
 childConn:Disconnect();gui:Destroy()
 if env.FourSkySwitcher==state then env.FourSkySwitcher=nil end
end
close.Activated:Connect(function()frame.Visible=false;reopen.Visible=true end)
reopen.Activated:Connect(function()frame.Visible=true;reopen.Visible=false end)
print('[tornhub] V8 DELTA: 37 skies + 19 texture launchers')
